import sys
import re

def sanitize_line(line: str) -> str:
    i = 0
    n = len(line)
    res = []

    def is_alnum(idx: int) -> bool:
        return 0 <= idx < n and line[idx].isalnum()

    while i < n:
        # Règle 1 : API Token
        # Précédé du début de ligne ou d'un caractère non alphanumérique
        if not is_alnum(i - 1) and line.startswith("token=", i):
            # Détection des répétitions consécutives de token=
            temp = i
            count = 0
            while temp + 6 <= n and line[temp:temp+6] == "token=":
                count += 1
                temp += 6

            if count >= 2:
                res.append(line[i:temp])
                i = temp
                continue

            val_start = i + 6
            val_end = val_start
            # La valeur est une suite purement alphanumérique (s'arrête sur '_' ou tout autre symbole)
            while val_end < n and line[val_end].isalnum():
                val_end += 1

            if val_end > val_start:
                res.append("token=[TOKEN_REDACTED]")
                i = val_end
                continue
            else:
                res.append("token=")
                i = val_start
                continue

        # Règle 2 : Carte de crédit
        # 4 groupes de 4 chiffres séparés par '-'
        if not is_alnum(i - 1):
            curr = i
            groups = []
            while True:
                if curr + 4 <= n and line[curr:curr+4].isdigit():
                    after = curr + 4
                    if after < n and line[after] == '-':
                        if after + 1 + 4 <= n and line[after+1:after+1+4].isdigit():
                            groups.append((curr, curr + 4))
                            curr = after + 1
                        else:
                            # Tiret isolé en fin de séquence
                            groups.append((curr, curr + 4))
                            curr = after
                            break
                    else:
                        if not is_alnum(after):
                            groups.append((curr, curr + 4))
                            curr = after
                        break
                else:
                    break

            if len(groups) == 4 and not is_alnum(curr):
                res.append("[CARD_REDACTED]")
                i = curr
                continue
            elif len(groups) >= 5:
                res.append(line[i:curr])
                i = curr
                continue

        # Caractère inchangé
        res.append(line[i])
        i += 1

    return "".join(res)

def main():
    input_data = sys.stdin.read().splitlines()
    if not input_data:
        return
    n = int(input_data[0])
    for line in input_data[1:n+1]:
        print(sanitize_line(line))

if __name__ == "__main__":
    main()
